import {createSpeaker} from './library-tools.js';
import {makeChoice,shuffle} from './choice-practice.js';
import {examplesHtml,phoneticsHtml,validFilters,matchingCards,printHtml} from './learning.js';
import {question,cloze} from './questions.js';
import {today,followingDay,grade,status,period} from './logic.js';
let cards=[],records={},db,view='home',queue=[],index=0,flipped=false,locked=false,mode='new',practiceKind='definition',currentChoice=null;
let offlineTranslations={},practiceSentences={};
let bookmark=null;
const BOOKMARK_KEY='bridge-reading-bookmark-v1';
try{bookmark=JSON.parse(localStorage.getItem(BOOKMARK_KEY)||'null')}catch{}
let filters={from:2,to:241,end:'',tag:'',state:'',search:''};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={new:'Not started',red:'Needs practice',yellow:'Learning',green:'Mastered'};
const rec=c=>records[c.id]||{id:c.id,streak:0,tags:[]};
function lamp(c){const r=rec(c),s=status(r);return `<span><i class="dot ${s}"></i>${labels[s]}${r.streak?' · '+r.streak+'/3':''}</span>`}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
async function put(r){await new Promise((resolve,reject)=>{const t=db.transaction('words','readwrite');t.objectStore('words').put(r);t.oncomplete=resolve;t.onerror=()=>reject(t.error)});records[r.id]=r}
function selected(){filters=validFilters(filters,cards,records);return matchingCards(cards,records,filters,status)}
function persistFilters(){try{sessionStorage.setItem('bridge-filters-book-pages-v2',JSON.stringify(filters))}catch{}}
function due(c){const r=rec(c);return r.due&&r.due<=today()&&r.streak<3}
function controls(){const tags=[...new Set(Object.values(records).flatMap(r=>r.tags||[]))].sort();return `<div class="filters"><label>Book start page <input id="from" type="number" min="2" max="241" value="${filters.from}" style="width:80px"></label><label>End page <input id="to" type="number" min="2" max="241" value="${filters.to}" style="width:80px"></label><select id="end" aria-label="Last word to include"><option value="">Through the last word in range</option>${cards.filter(c=>c.page>=filters.from&&c.page<=filters.to).map(c=>`<option value="${c.id}" ${c.id===filters.end?'selected':''}>p.${c.page} · ${esc(c.word)}</option>`).join('')}</select><select id="tag" aria-label="Tags"><option value="">All tags</option>${tags.map(t=>`<option ${t===filters.tag?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="state" aria-label="Mastery level"><option value="">All levels</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===filters.state?'selected':''}>${v}</option>`).join('')}</select></div>`}
function bindFilters(){for(const k of ['from','to','end','tag','state'])$('#'+k)?.addEventListener('change',e=>{filters[k]=['from','to'].includes(k)?Math.max(2,Math.min(241,Number(e.target.value)||2)):e.target.value;if(['from','to'].includes(k))filters.end='';if(filters.to<filters.from)filters.to=filters.from;persistFilters();visible=80;queue=[];render()})}
function title(eyebrow,heading,sub){return `<div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p class="sub">${sub}</p>`}
const translations=new Map(),speaker=createSpeaker();
function chinese(text,visible=true){return text?`<p class="chinese-translation" lang="zh-Hant"${visible?'':' style="visibility:hidden" aria-hidden="true"'}>${esc(text)}</p>`:''}
function audioButton(c,part){return `<button class="btn outline audioButton" data-id="${c.id}" data-part="${part}" aria-pressed="false" aria-label="Listen to ${part==='word'?'word or phrase':'example '+(Number(part)+1)}">▷ Listen</button>`}
function row(c,withExample=false){const t=translations.get(c.id),zh=withExample?(t?.data||offlineTranslations[c.id]):null;return `<div class="word-row"><div><div class="word-heading"><strong>${esc(c.word)}</strong>${zh?.word?`<span class="word-chinese" lang="zh-Hant"${t?.open?'':' style="visibility:hidden" aria-hidden="true"'}>${esc(zh.word)}</span>`:''}</div>${phoneticsHtml(c)}${withExample?audioButton(c,'word'):''}<br><small>Book p.${c.page} · ${esc((rec(c).tags||[]).join(' / '))}</small></div><div>${esc(withExample?c.meaning:c.meaning.slice(0,110))}${chinese(zh?.meaning,!!t?.open)}${withExample?`<div class="library-example"><span>Examples</span>${c.examples.length?c.examples.map((e,i)=>`<div class="library-sentence"><p class="example-line">${esc(e)} ${audioButton(c,i)}</p>${chinese(zh?.examples?.[i],!!t?.open)}</div>`).join(''):'<p class="muted">No example available in this entry.</p>'}</div>`:""}</div><small>${lamp(c)}</small></div>`}
function translationButton(c){const t=translations.get(c.id);return `<button class="btn outline translationButton" data-id="${c.id}" aria-expanded="${!!t?.open}" aria-controls="translation-status-${c.id}">${t?.open?'Hide Chinese translation':'Show Chinese translation'}</button><p class="translation-status sub" style="visibility:${t?.open?'visible':'hidden'}" id="translation-status-${c.id}" aria-live="polite">${esc('Preloaded · Available offline')}</p>`}
function paintTranslation(c){const entry=document.getElementById('word-'+c.id);if(!entry)return;entry.querySelector('.word-row').outerHTML=row(c,true);const b=entry.querySelector('.translationButton'),t=translations.get(c.id);b.textContent=t.open?'Hide Chinese translation':'Show Chinese translation';b.setAttribute('aria-expanded',String(t.open));entry.querySelector('.translation-status').style.visibility=t.open?'visible':'hidden';bindLibraryAudio()}
function toggleTranslation(c){let t=translations.get(c.id);if(!t){t={open:false,data:offlineTranslations[c.id]||null};translations.set(c.id,t)}t.open=!t.open;paintTranslation(c)}
function bindLibraryAudio(){document.querySelectorAll('.audioButton').forEach(b=>b.onclick=()=>{const c=cards.find(c=>c.id===b.dataset.id),part=b.dataset.part;try{speaker.speak(part==='word'?c.word:c.examples[Number(part)],c.id+':'+part,id=>document.querySelectorAll('.audioButton').forEach(button=>{const active=button.dataset.id+':'+button.dataset.part===id;button.textContent=active?'■ Stop':'▷ Listen';button.setAttribute('aria-pressed',String(active))}))}catch(e){toast(e.message)}})}


function saveBookmark(c,where=view,notify=false){
 const saved={id:c.id,view:where,filters:{...filters},savedAt:new Date().toISOString()};
 try{localStorage.setItem(BOOKMARK_KEY,JSON.stringify(saved));bookmark=saved;if(notify)toast('Bookmark saved · '+c.word)}catch{if(notify)toast('Could not save bookmark. Allow this site to store data.')}
}
function bookmarkButton(c){const active=bookmark?.id===c.id;return `<button class="btn outline bookmarkButton ${active?'is-bookmarked':''}" data-id="${c.id}" aria-pressed="${active}" aria-label="${active?'Remove bookmark for':'Bookmark'} ${esc(c.word)}"><span class="bookmark-light" aria-hidden="true"></span>${active?'Bookmarked':'Bookmark'}</button>`}
function syncBookmarkButtons(){document.querySelectorAll('.bookmarkButton').forEach(b=>{const active=b.dataset.id===bookmark?.id;b.classList.toggle('is-bookmarked',active);b.setAttribute('aria-pressed',String(active));const c=cards.find(c=>c.id===b.dataset.id);b.setAttribute('aria-label',(active?'Remove bookmark for ':'Bookmark ')+(c?.word||''));b.innerHTML='<span class="bookmark-light" aria-hidden="true"></span>'+(active?'Bookmarked':'Bookmark')})}
function toggleBookmark(c,where=view){
 if(bookmark?.id===c.id){try{localStorage.setItem(BOOKMARK_KEY,'null');bookmark=null;toast('Bookmark removed')}catch{toast('Could not remove bookmark. Allow this site to store data.')}}
 else saveBookmark(c,where,true);
 if(view==='home')render();else syncBookmarkButtons();
}
function bindBookmarkButtons(){document.querySelectorAll('.bookmarkButton').forEach(b=>b.onclick=()=>{const c=cards.find(c=>c.id===b.dataset.id);if(c)toggleBookmark(c)})}
function bookmarkCard(){const c=cards.find(c=>c.id===bookmark?.id);return `<section class="panel reading-bookmark" aria-label="Reading bookmark"><div><div class="eyebrow" style="margin:0">YOUR BOOKMARK</div><h2>Continue reading</h2>${c?`<p><strong>${esc(c.word)}</strong> ${phoneticsHtml(c)}<br><span class="sub">Book p.${c.page} · ${bookmark.view==='library'?'Word library':'Study cards'}</span></p>`:'<p class="sub">Select Bookmark beside a word to save your place. Select it again to remove the bookmark.</p>'}</div>${c?`<div class="actions"><button id="resumeReading" class="btn">Continue from here →</button>${bookmarkButton(c)}</div>`:''}</section>`}
function resumeReading(){
 const c=cards.find(c=>c.id===bookmark?.id);if(!c)return toast('This bookmarked word is unavailable.');
 const saved={...bookmark};filters=validFilters({...filters,...saved.filters},cards,records);
 if(!selected().some(w=>w.id===c.id))filters={from:2,to:241,end:'',tag:'',state:'',search:''};
 persistFilters();view=saved.view==='library'?'library':saved.view==='quiz'?'quiz':'cards';mode='new';
 if(view==='library'){visible=Math.max(80,selected().findIndex(w=>w.id===c.id)+1);render();requestAnimationFrame(()=>{const el=document.getElementById('word-'+c.id);el?.scrollIntoView({block:'center',behavior:'smooth'});el?.focus({preventScroll:true})})}
 else{render();index=queue.findIndex(w=>w.id===c.id);flipped=false;locked=false;showCard();$('#studyBody')?.scrollIntoView({block:'start',behavior:'smooth'})}
}

function home(){const pending=cards.filter(due),counts=Object.keys(labels).map(s=>cards.filter(c=>status(rec(c))===s).length),learned=cards.length-counts[0];return title('A LITTLE EVERY DAY','Build a bridge, word by word.','From reading to remembering. A little progress every day starts here.')+`${bookmarkCard()}<div class="hero"><section class="panel feature"><div class="eyebrow" style="color:#b7ceba;margin-top:0">TODAY’S REVIEW</div><h2 style="margin-top:20px">Reconnect with what you learned.</h2><div class="big">${pending.length}<span style="font-size:14px;margin-left:12px">words due for review</span></div><p>Meet yesterday’s challenging words again today.</p><button class="btn" id="review">Start today’s review ↗</button><div class="bridge"></div></section><section class="panel"><div class="eyebrow" style="margin-top:0">YOUR BOOK</div><h2 style="font-family:Georgia;font-size:32px;margin-top:18px">THE BRIDGE</h2><p class="sub">${cards.length.toLocaleString()} word and phrase cards · In book order<br>Book pages 2–241 (printed page numbers)</p><div class="progress"><i style="width:${learned/cards.length*100}%"></i></div><div class="row sub"><span>Started ${learned} / ${cards.length}</span><button class="btn outline" id="explore">Browse library →</button></div></section></div><div class="stats">${Object.keys(labels).map((s,i)=>`<div class="stat"><span><i class="dot ${s}"></i>${labels[s]}</span><strong>${counts[i].toLocaleString()}</strong></div>`).join('')}</div><section class="panel"><div class="section-head"><h2>Choose your study range</h2><span class="sub">By page, at your own pace</span></div>${controls()}<div class="row"><span class="sub">In range: ${selected().length} words</span><button id="start" class="btn">Practice this range →</button></div></section><section style="margin-top:30px"><div class="section-head"><h2>Words to revisit</h2><span class="sub">3 correct sessions in a row → Green</span></div>${pending.length?pending.slice(0,5).map(c=>row(c)).join(''):'<div class="panel sub">No reviews due today. Start with flashcards or choose a page range to practice.</div>'}</section>`}
function study(){return title(view==='quiz'?'RECALL & GROW':'READ · FLIP · REMEMBER',view==='quiz'?'Make your memory last.':'One card. One new connection.',view==='quiz'?'Choose a clue type. Each round is shuffled and uses four similar English answers. Sentence blanks can use original examples or new practice sentences. All Chinese clues are preloaded for offline practice.':'Recall first, then flip. Your self-assessment updates mastery and next-day reviews.')+controls()+`<div class="actions"><button class="btn ${mode==='new'?'':'outline'}" id="allStudy">Practice this range</button><button class="btn ${mode==='due'?'':'outline'}" id="dueStudy">Due words only</button><span class="sub">${selected().length} words in range</span></div>${view==='quiz'?`<div class="actions practice-modes" role="group" aria-label="Practice mode"><button class="btn ${practiceKind==='chinese'?'':'outline'}" data-practice="chinese">Chinese → English (${Object.keys(offlineTranslations).length} cards)</button><button class="btn ${practiceKind==='definition'?'':'outline'}" data-practice="definition">Definition → English</button><button class="btn ${practiceKind==='sentence'?'':'outline'}" data-practice="sentence">Sentence blank → English</button></div>`:''}<div id="studyBody" class="card-area"></div>`}
function showCard(){const host=$('#studyBody');if(!host)return;const c=queue[index];if(!c){host.innerHTML=`<div class="panel empty"><h2>${queue.length?'Round complete.':'No words match your selection.'}</h2><p>${queue.length?'Progress saved. Words still being learned will return tomorrow.':'Adjust your pages or tags, or choose Practice this range.'}</p><button id="restart" class="btn">Start a fresh round</button></div>`;$('#restart').onclick=()=>start(mode);return}const r=rec(c),q=view==='quiz'?makeChoice(c,cards,practiceKind,offlineTranslations[c.id],Math.random,practiceSentences[c.id]||[]):question(c,index%2===1);currentChoice=view==='quiz'?q:null;host.innerHTML=`<div class="row sub"><span>${index+1} / ${queue.length} · Book p.${c.page}</span>${lamp(c)}</div>${bookmarkButton(c)}<div class="progress"><i style="width:${index/queue.length*100}%"></i></div><div class="flash">${view==='cards'?`<div class="eyebrow" style="margin:0">WORD / PHRASE</div><h2>${esc(c.word)}</h2>${phoneticsHtml(c)}<button id="speak" class="btn outline" aria-label="Read word aloud">▷ Listen</button>${flipped?`<p class="meaning">${esc(c.meaning)}</p><div class="card-examples">${examplesHtml(c)}</div>`:'<p>Recall its meaning, then reveal the answer.</p><button id="flip" class="btn">Flip card ↻</button>'}`:`<div class="eyebrow" style="margin:0">${esc(q?.kind||practiceKind)}</div><p class="meaning">${esc(q?.text||'Question not available in this mode.')}</p><div class="choice-options">${(q?.options||[]).map((o,i)=>`<button class="btn outline choice-option" data-choice="${esc(o.id)}"><span class="choice-letter">${String.fromCharCode(65+i)}</span>${esc(o.text)}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div>`}</div><div class="actions" id="grading">${view==='cards'&&flipped?'<button id="wrong" class="btn outline">Still learning · Review tomorrow</button><button id="correct" class="btn">I remembered ✓</button>':''}<button id="skip" class="btn outline">Skip without grading →</button></div><div class="panel"><div class="row"><span class="sub">Custom tags · ${esc((r.tags||[]).join(' / ')||'No tags yet')}</span><button class="btn outline" id="editTags">Edit tags</button></div><div id="tagEditor"></div></div>`;
bindBookmarkButtons();$('#flip')?.addEventListener('click',()=>{flipped=true;showCard()});$('#speak')?.addEventListener('click',()=>{if(!('speechSynthesis'in window))return toast('Speech is not supported in this browser.');const u=new SpeechSynthesisUtterance(c.word);u.lang='en-US';speechSynthesis.speak(u)});$('#skip').onclick=next;$('#wrong')?.addEventListener('click',()=>rate(false));$('#correct')?.addEventListener('click',()=>rate(true));document.querySelectorAll('.choice-option').forEach(b=>b.onclick=()=>checkChoice(b.dataset.choice));$('#editTags').onclick=()=>editTags(c,$('#tagEditor'))}
function next(){index++;flipped=false;locked=false;showCard()}
async function rate(ok){if(locked)return;locked=true;try{await put(grade(rec(queue[index]),ok));next()}catch(e){locked=false;toast('Could not save. Export a backup and try again.')}}
function norm(s){return s.toLowerCase().trim().replace(/[’‘]/g,"'").replace(/\s+/g,' ').replace(/[.!?]$/,'')}
async function check(force){if(locked)return;const c=queue[index],answer=$('#answer').value;const alternatives=question(c,index%2===1).answers.flatMap(a=>a.split(/\s*[=;]\s*/)).map(norm);const ok=force===false?false:alternatives.includes(norm(answer));locked=true;try{await put(grade(rec(c),ok));$('#submit').disabled=true;$('#dontKnow').disabled=true;$('#answer').disabled=true;$('#feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?'Correct ✓':'Another chance to remember.'}</strong><br>Answer: ${esc(c.word)} ${phoneticsHtml(c)}<br>Definition: ${esc(c.meaning)}<br>Examples: <div class="feedback-examples">${examplesHtml(c)}</div><small>${rec(c).streak>=3?'Three consecutive correct sessions. Now green!':'Scheduled for '+rec(c).due+' review.'} Repeats within the same morning, afternoon, or evening do not add to your streak.</small></div>`;$('#grading').innerHTML='<button id="next" class="btn">Next word →</button>';$('#next').onclick=next}catch(e){locked=false;toast('Could not save. This answer has not been recorded.')}}
async function checkChoice(chosen){if(locked)return;const c=queue[index],q=currentChoice;if(!q)return;const ok=chosen===q.correctId;locked=true;try{await put(grade(rec(c),ok));document.querySelectorAll('.choice-option').forEach(b=>{b.disabled=true;b.classList.toggle('choice-correct',b.dataset.choice===q.correctId);b.classList.toggle('choice-wrong',b.dataset.choice===chosen&& !ok)});$('#feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?'Correct ✓':'Another chance to remember.'}</strong><br>Answer: ${esc(c.word)} ${phoneticsHtml(c)}<br>Definition: ${esc(c.meaning)}<br>Examples: <div class="feedback-examples">${examplesHtml(c)}</div><small>${rec(c).streak>=3?'Three consecutive correct sessions. Now green!':'Scheduled for '+rec(c).due+' review.'} Repeats within the same morning, afternoon, or evening do not add to your streak.</small></div>`;$('#grading').innerHTML='<button id="next" class="btn">Next word →</button>';$('#next').onclick=next}catch(e){locked=false;toast('Could not save. This answer has not been recorded.')}}
function editTags(c,host){host.innerHTML=`<p class="sub">Separate tags with commas. Remove a tag to delete it.</p><input id="tagsInput" aria-label="Tag names" placeholder="Tricky words, Phrases, Exam prep" value="${esc((rec(c).tags||[]).join(', '))}"> <button id="saveTags" class="btn">Save</button>`;$('#saveTags').onclick=async()=>{try{await put({...rec(c),tags:[...new Set($('#tagsInput').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean))]});filters=validFilters(filters,cards,records);persistFilters();toast('Tags saved');if(view==='library')render();else showCard()}catch(e){toast('Could not save tags')}}}
let visible=80;
function libraryResults(){const list=selected();return `<div class="panel">${list.slice(0,visible).map(c=>`<div class="library-entry" id="word-${c.id}" tabindex="-1">${row(c,true)}${translationButton(c)}${bookmarkButton(c)} <button class="btn outline tagButton" data-id="${c.id}">Edit tags</button><div id="editor-${c.id}"></div></div>`).join('')||'<p class="empty">No matching words. Try another search or reset your filters.</p>'}</div>${list.length>visible?'<div class="actions"><button id="more" class="btn outline">Load more</button></div>':''}`}
function library(){const list=selected();return title('THE WORD COLLECTION','Your word map.','Browse in printed page order, select a range, or connect your learning with custom tags.')+controls()+`<div class="filters"><input id="search" type="search" placeholder="Search words, definitions or examples…" aria-label="Search library" value="${esc(filters.search)}"><button id="clearFilters" class="btn outline">Reset filters</button><button id="printRange" class="btn" ${list.length?'':'disabled'}>Print selected range</button><span id="resultCount" class="sub">${list.length} results</span></div><p class="sub">Use Listen for device voice playback. Traditional Chinese translations for all ${Object.keys(offlineTranslations).length.toLocaleString()} entries are preloaded. Wait for Ready for offline use before disconnecting. Printing includes every matching word, including entries beyond Load more.</p><div id="libraryResults">${libraryResults()}</div>`}
function bindLibraryResults(){bindLibraryAudio();document.querySelectorAll('.translationButton').forEach(b=>b.onclick=()=>toggleTranslation(cards.find(c=>c.id===b.dataset.id)));bindBookmarkButtons();$('#more')?.addEventListener('click',()=>{visible+=80;refreshLibrary()});document.querySelectorAll('.tagButton').forEach(b=>b.onclick=()=>editTags(cards.find(c=>c.id===b.dataset.id),$('#editor-'+b.dataset.id)))}
function refreshLibrary(){$('#libraryResults').innerHTML=libraryResults();const count=selected().length;$('#resultCount').textContent=count+' results';$('#printRange').disabled=!count;bindLibraryResults()}
function preparePrint(){const root=$('#printRoot');root.innerHTML=printHtml(cards,records,filters,status);return selected().length}
window.addEventListener('beforeprint',preparePrint);

function start(m='new'){mode=m;const source=selected().filter(c=>m!=='due'||due(c));queue=view==='quiz'?shuffle(source.filter(c=>practiceKind==='chinese'?!!offlineTranslations[c.id]?.word:practiceKind==='sentence'?!!cloze(c,practiceSentences[c.id]||[]):true)):source;index=0;flipped=false;locked=false;showCard()}
function render(){filters=validFilters(filters,cards,records);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=view==='home'?home():view==='library'?library():study();bindFilters();if(view==='home'){bindBookmarkButtons();$('#resumeReading')?.addEventListener('click',resumeReading);$('#review').onclick=()=>{view='quiz';mode='due';render()};$('#explore').onclick=()=>{view='library';render()};$('#start').onclick=()=>{view='quiz';mode='new';render()}}else if(view==='library'){$('#search').oninput=e=>{filters.search=e.target.value;visible=80;persistFilters();refreshLibrary()};$('#clearFilters').onclick=()=>{filters={from:2,to:241,end:'',tag:'',state:'',search:''};visible=80;persistFilters();render();$('#search').focus()};$('#printRange').onclick=()=>{if(preparePrint())window.print();else toast('No words selected for printing.')};bindLibraryResults()}else{$('#allStudy').onclick=()=>start('new');$('#dueStudy').onclick=()=>start('due');document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{practiceKind=b.dataset.practice;render()});start(mode)}}

document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{speaker.stop();view=b.dataset.view;mode='new';render()});
$('#date').textContent=new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',weekday:'long'}).format(new Date())+' · '+period().toUpperCase();
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,book:'THE BRIDGE',records:Object.values(records)},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bridge-progress-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.version!==1||data.book!=='THE BRIDGE'||!Array.isArray(data.records))throw Error();const ids=new Set(cards.map(c=>c.id));for(const r of data.records){if(!ids.has(r.id)||!Number.isInteger(r.streak)||r.streak<0||r.streak>3||!Array.isArray(r.tags)||r.tags.some(t=>typeof t!=='string')||['due','lastCorrect','lastAttempt'].some(k=>r[k]!=null&&!/^\d{4}-\d{2}-\d{2}$/.test(r[k])))throw Error()}const tx=db.transaction('words','readwrite');data.records.forEach(r=>tx.objectStore('words').put(r));await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=rej});data.records.forEach(r=>records[r.id]=r);toast('Progress imported and merged');render()}catch(e){toast('Import failed. Choose a valid progress backup.')}$('#file').value=''};
try{[cards,offlineTranslations,practiceSentences]=await Promise.all([fetch('cards.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('offline-translations.json').then(r=>r.ok?r.json():{}).catch(()=>({})),fetch('practice-sentences.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]);db=await new Promise((resolve,reject)=>{const r=indexedDB.open('the-bridge-study',1);r.onupgradeneeded=()=>r.result.createObjectStore('words',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const rows=await new Promise((resolve,reject)=>{const r=db.transaction('words').objectStore('words').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=reject});rows.forEach(r=>records[r.id]=r);try{filters={...filters,...JSON.parse(sessionStorage.getItem('bridge-filters-book-pages-v2')||'{}')}}catch{}$('#dbState').textContent='● Device database connected';render();setInterval(()=>{if(view==='home')render()},60000)}catch(e){$('#content').innerHTML='<div class="panel"><h1>Unable to open your learning data</h1><p>Use a regular browser window, allow this site to store data, then refresh.</p></div>';$('#dbState').textContent='Database disconnected'}


// Keep the compact phone navigation available when scrolling back toward earlier words.
const phoneNavigation=window.matchMedia('(max-width:600px)');
let navigationY=window.scrollY,navigationTravel=0,navigationDirection=0,navigationFrame=false;
window.addEventListener('scroll',()=>{if(navigationFrame)return;navigationFrame=true;requestAnimationFrame(()=>{navigationFrame=false;const y=Math.max(0,window.scrollY),delta=y-navigationY;navigationY=y;if(!phoneNavigation.matches||y<24){document.body.classList.remove('mobile-nav-hidden');navigationTravel=0;return}const direction=Math.sign(delta);if(direction!==navigationDirection){navigationTravel=0;navigationDirection=direction}navigationTravel+=Math.abs(delta);if(navigationTravel>=12)document.body.classList.toggle('mobile-nav-hidden',direction>0)})},{passive:true});
phoneNavigation.addEventListener('change',()=>{document.body.classList.remove('mobile-nav-hidden');navigationY=window.scrollY;navigationTravel=0});
